def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    change = new - old
    return {
        "value": change,
        "trace": {
            "old_value": old,
            "new_value": new,
            "change": change,
            "output_meta": {
                "currency": "EUR",
                "scale": None,
                "unit": "per ordinary share"
            }
        }
    }
